#include <bits/stdc++.h>
#include <omp.h>
using namespace std;
struct L{int a,b,c;bool operator==(L const&o)const{return a==o.a&&b==o.b&&c==o.c;}};
struct H{size_t operator()(L const&x)const noexcept{return ((uint64_t)(x.a+100)<<42)^((uint64_t)(x.b+100)<<32)^(uint32_t)(x.c+100000);}};
vector<int>pl;int C2[61],C3[61],INV[1771],NL;L canon(int x1,int y1,int x2,int y2){int A=y2-y1,B=x1-x2,C=A*x1+B*y1,g=gcd(abs(A),gcd(abs(B),abs(C)));if(g)A/=g,B/=g,C/=g;if(A<0||(A==0&&B<0))A=-A,B=-B,C=-C;return{A,B,C};}
void init(){unordered_map<L,int,H>m;m.reserve(240000);pl.assign(810000,-1);int z=0;for(int u=0;u<900;u++)for(int v=u+1;v<900;v++){auto q=canon(u/30,u%30,v/30,v%30);auto[it,n]=m.emplace(q,z);if(n)z++;pl[u*900+v]=pl[v*900+u]=it->second;}NL=z;for(int k=0;k<=60;k++){C2[k]=k*(k-1)/2;C3[k]=k*(k-1)*(k-2)/6;INV[C2[k]]=k;}}
struct Job{array<unsigned char,6>re{},be{};unsigned char nr=0,nb=0;};
struct W{vector<int>mark,freq,paircnt,touched,ids,cells,R,B,rv,bv;int stamp=1,pot=0;array<unsigned char,30>ra{},ba{},ru{},bu{};long long nodes=0;W():mark(NL),freq(NL),paircnt(NL){touched.reserve(1800);ids.reserve(60);cells.reserve(60);}void clear(){for(int id:touched)paircnt[id]=0;touched.clear();cells.clear();fill(ra.begin(),ra.end(),0);fill(ba.begin(),ba.end(),0);fill(ru.begin(),ru.end(),0);fill(bu.begin(),bu.end(),0);pot=0;}bool add(int c){if(++stamp==INT_MAX){fill(mark.begin(),mark.end(),0);stamp=1;}ids.clear();for(int q:cells){int id=pl[c*900+q];if(mark[id]!=stamp){mark[id]=stamp;freq[id]=0;ids.push_back(id);}freq[id]++;}int d=0;for(int id:ids)d+=C2[freq[id]];if(pot+d>2)return false;pot+=d;cells.push_back(c);return true;}void rem(int p){cells.pop_back();pot=p;}bool build(const Job&j,const vector<int>&r0,const vector<int>&b0,const vector<int>&RB,const vector<int>&BB){clear();R=RB;B=BB;for(int k=0;k<j.nr;k++)R.push_back(j.re[k]);for(int k=0;k<j.nb;k++)B.push_back(j.be[k]);array<unsigned char,30>rm{},bm{};for(int x:R)rm[x]=1;for(int x:B)bm[x]=1;for(int i=0;i<30;i++){if(!rm[i]){ra[i]=r0[i];cells.push_back(i*30+r0[i]-1);}if(!bm[i]){ba[i]=b0[i];cells.push_back(i*30+b0[i]-1);}}for(int i=0;i<(int)cells.size();i++)for(int k=0;k<i;k++){int id=pl[cells[i]*900+cells[k]];if(paircnt[id]++==0)touched.push_back(id);}pot=0;for(int id:touched)pot+=C3[INV[paircnt[id]]];if(pot>2)return false;rv.clear();bv.clear();for(int x:R)rv.push_back(r0[x]);for(int x:B)bv.push_back(b0[x]);return true;}bool dfs(int d,const vector<pair<int,int>>&ord){nodes++;if(d==(int)ord.size())return true;auto[l,row]=ord[d];auto&vals=l?bv:rv;auto&used=l?bu:ru;auto&ass=l?ba:ra;auto&opp=l?ra:ba;for(int k=0;k<(int)vals.size();k++){int y=vals[k];if(used[k]||(opp[row]&&opp[row]==y))continue;int old=pot;if(!add(row*30+y-1))continue;used[k]=1;auto oa=ass[row];ass[row]=y;if(dfs(d+1,ord))return true;ass[row]=oa;used[k]=0;rem(old);}return false;}};
int main(int argc,char**argv){init();int si=argc>1?atoi(argv[1]):-1;if(si<0||si>=32)return 2;struct S{long long nr,lo,hi,en;};S ss[32]={{0,0,177100,35678890},{1,0,500000,72454278},{1,500000,1000000,70528822},{1,1000000,1381380,59380541},{2,0,750000,78343390},{2,750000,1500000,88246388},{2,1500000,2250000,79597203},{2,2250000,3000000,90087376},{2,3000000,3750000,84712359},{2,3750000,4111250,46368471},{3,0,500000,43527834},{3,500000,1000000,47398791},{3,1000000,1500000,47083933},{3,1500000,2000000,45227886},{3,2000000,2500000,49218031},{3,2500000,3000000,54575439},{3,3000000,3500000,47839434},{3,3500000,4000000,40880803},{3,4000000,4500000,60497458},{3,4500000,5000000,44582148},{3,5000000,5500000,44852772},{3,5500000,5980000,51756364},{4,0,750000,64926409},{4,750000,1500000,71945821},{4,1500000,2250000,68341313},{4,2250000,3000000,75819652},{4,3000000,3750000,68224169},{4,3750000,4485000,67131202},{5,0,500000,51155065},{5,500000,1000000,52372669},{5,1000000,1644500,65537290},{6,0,230230,29657917}};auto sh=ss[si];int f=sh.nr;long long lo=sh.lo,hi=sh.hi;vector<int>r0={12,15,24,9,27,20,4,17,28,29,6,2,8,13,1,18,7,19,23,11,26,30,10,5,14,3,21,22,25,16},b0={17,10,21,22,7,15,8,28,25,13,9,4,20,26,30,12,27,24,29,23,14,1,2,11,18,6,3,16,5,19},RB={13,15,19,22},BB={8,13,17,19,28},RE,BE;for(int i=0;i<30;i++){if(find(RB.begin(),RB.end(),i)==RB.end())RE.push_back(i);if(find(BB.begin(),BB.end(),i)==BB.end())BE.push_back(i);}vector<vector<int>>RC,BC;vector<int>cur;function<void(const vector<int>&,int,int,vector<vector<int>>&)>gen=[&](const vector<int>&a,int k,int st,vector<vector<int>>&out){if((int)cur.size()==k){out.push_back(cur);return;}for(int i=st;i<=(int)a.size()-(k-(int)cur.size());i++){cur.push_back(a[i]);gen(a,k,i+1,out);cur.pop_back();}};gen(RE,f,0,RC);cur.clear();gen(BE,6-f,0,BC);vector<Job>jobs;for(auto const&rr:RC)for(auto const&bb:BC){Job j;j.nr=f;j.nb=6-f;for(int i=0;i<f;i++)j.re[i]=rr[i];for(int i=0;i<6-f;i++)j.be[i]=bb[i];jobs.push_back(j);}atomic<bool>found(false);atomic<long long>done(0),nodes(0);
#pragma omp parallel num_threads(8)
{W w;
#pragma omp for schedule(dynamic,1)
for(long long ji=lo;ji<hi;ji++){if(found.load())continue;auto&j=jobs[ji];if(!w.build(j,r0,b0,RB,BB)){done++;continue;}vector<pair<int,int>>ord;for(int x:w.R)ord.push_back({0,x});for(int x:w.B)ord.push_back({1,x});stable_sort(ord.begin(),ord.end(),[&](auto a,auto b){int oa=a.first?w.ra[a.second]:w.ba[a.second],ob=b.first?w.ra[b.second]:w.ba[b.second];return(oa!=0)>(ob!=0);});if(w.dfs(0,ord))found=true;done++;nodes+=w.nodes;w.nodes=0;}}
if(found)return 1;assert(done==hi-lo&&nodes==sh.en);cout<<"AC p31 support-six shard\n"<<"shard: "<<si<<"\n"<<"red_extras: "<<f<<"\n"<<"support_lo: "<<lo<<"\n"<<"support_hi: "<<hi<<"\n"<<"support_choices: "<<done<<"\n"<<"partial_states: "<<nodes<<"\n"<<"complete_potential_at_most_two_states: 0\n";}
